end)

check("a seat is worth loyalty to the party that holds it", function()
    -- A COMPARISON, NOT AN ABSOLUTE. "A seated party's loyalty goes up and an
    -- unseated one's goes down" is false once a party has traits: a party with
    -- Grasping and a thirsty leader loses ground while holding a seat, and one
    -- with Dutiful gains while holding none. Those are the traits doing their job.
    --
    -- What a seat means is this: the same party, with the seat and without,
    -- differs by exactly what the seat is worth.
    IC.state = {}
    turn = 1
    local a = make_character(1, ANY_SEAT, "forge")
    make_faction(F, IC.CHD_SUBCULTURE, {a}, {})
    IC.add_house(F, "forge"); IC.add_house(F, "legion")
    endow(F)
    local without = IC.loyalty_net(IC.loyalty_terms(F, "forge"))
    IC.appoint(F, "forge", 1)
    local with = IC.loyalty_net(IC.loyalty_terms(F, "forge"))
    assert(with > without,
        "a seat left the party drifting at " .. with .. " against " .. without)

    -- AND A PARTY HOLDING NOTHING IS STILL CHARGED FOR IT, whatever its traits
    -- then do about the total.
    local idle = nil
    for _, t in ipairs(IC.loyalty_terms(F, "legion")) do
        if t.label == "No seat at court" then idle = t end
    end
    assert(idle and idle.n == IC.TUNE.loyalty_drift_none,
        "a house with nothing is not charged the idle drift")
end)

check("loyalty is clamped to 0..100", function()
    IC.state = {}
    IC.add_house(F, "legion")
    local court = IC.court(F)
    court.houses["legion"].loyalty = 0
    for _ = 1, 50 do IC.drift_loyalty(F) end
    assert(court.houses["legion"].loyalty >= 0, "never negative")
    court.houses["legion"].loyalty = 100
    assert(court.houses["legion"].loyalty <= 100, "never above 100")
end)

check("removing a house takes its office and governorship with it", function()
    IC.state = {}
    turn = 1
    local drazak = make_character(2, ANY_SEAT, "crown", "prov_a")
    make_faction(F, IC.CHD_SUBCULTURE, {drazak}, {"prov_a"})
    IC.add_house(F, "crown")
    endow(F)
    IC.appoint(F, "chains", 2)
    IC.assign_governor(F, "prov_a", 2)
    assert(IC.court(F).offices["chains"] == 2, "office held")
    assert(IC.court(F).govs["prov_a"] == 2, "governorship held")
    IC.remove_house(F, "crown")
    assert(IC.court(F).offices["chains"] == nil, "office released with the house")
    assert(IC.court(F).govs["prov_a"] == nil, "governorship released with the house")
end)

-- The panel file: opener placement and the standing bar. These are the two
-- pieces of real arithmetic in the UI and both are checkable with no game
-- running; placement especially, since every wrong anchor is otherwise found
-- in play.
local ui_stub = {}

-- resources_bar, as measured live on a 1920x1080 screen: pos 431,-4, 1019x60.
local BAR_X, BAR_Y, BAR_W, BAR_H = 431, -4, 1019, 60

-- CA's `out`, built the way all_scripted.lua builds it: a TABLE of per-channel
-- functions made callable with a __call metamethod. Modelled as a plain
-- function, `type(out) == "function"` passes here while it is false in every
-- real campaign, and the panel's whole diagnostic log is dead.
logged = {}
out = setmetatable({
    design = function(s) logged[#logged + 1] = tostring(s) end,
    ui = function(s) logged[#logged + 1] = tostring(s) end,
}, {__call = function(_t, s) logged[#logged + 1] = tostring(s) end})

local function install_ui_stubs(bar_y)
    ui_stub.bar = {
        is_null_interface = function() return false end,
        Position = function() return BAR_X, bar_y or BAR_Y end,
        Dimensions = function() return BAR_W, BAR_H end,
    }
    find_uicomponent = function(_parent, name)
        if name == "resources_bar" then return ui_stub.bar end
        return false
    end
    is_uicomponent = function(c) return type(c) == "table" and c.Position ~= nil end
    -- PORTHOLES. The panel reads CcoCampaignCharacter.PortraitPath, which is a
    -- VOID-argument property - and that is the only kind that may go through
    -- get_context_value at all, because a PARAMETERISED CCO call null-derefs the
    -- game at Warhammer3.exe+0x1F368AC where pcall cannot reach it.
    --
    -- The stub returns "" for an id it does not know, because that is what the
    -- engine does: an absent context id reads back as the EMPTY STRING, which is
    -- TRUTHY in Lua. A caller that tests only `if path then` therefore passes an
    -- empty imagepath to SetImagePath, which draws a blank square and logs
    -- nothing. That is the fault this stub exists to catch.
    IC_TEST_PORTRAITS = {}      -- PortraitPath  : the porthole, 300x164 landscape
    IC_TEST_CARDS = {}          -- ImageCardPath : the army card, 60x130 tall
    IC_TEST_LOC = {}
    -- cco() is a bare global in campaign Lua, not a member of cm or common.
    -- The real one returns an engine context object; all this file needs is
    -- something that remembers which object was asked for.
    cco = function(object, id) return {cco = object, id = tostring(id)} end

    common = {
        -- Seeded entries win; everything else answers with NOTHING, which is what the
        -- engine does with a key the game has not got. The key itself reaching the
        -- screen is the panel's own loc() falling back to it; modelling that here as
        -- well would make this stub disagree with the engine for a caller passing its
        -- own fallback, and a house comes out named
        -- "factions_screen_name_cr_chd_warfleet_of_uzkulak".
        get_localised_string = function(k) return IC_TEST_LOC[k] or "" end,
        -- KEYED ON THE PROPERTY. A stub that ignores it cannot tell whether the office
        -- card asked for ImageCardPath or for PortraitPath, and those are different
        -- pictures in different ORIENTATIONS.
        get_context_value = function(_object, id, property)
            local t = IC_TEST_PORTRAITS
            if property == "ImageCardPath" then t = IC_TEST_CARDS end
            return t[tostring(id)] or ""
        end,
        -- ICUI.confirm wraps this in a pcall, so with no stub every click
        -- confirmation would "work" by quietly erroring.
        trigger_soundevent = function(name)
            sounds[#sounds + 1] = name
        end,
    }
    -- The pulse, recorded as (component id, on/off) in the order it was asked
    -- for. The ORDER is the point: a pulse nothing turns off runs until the
    -- panel is destroyed.
    pulse_uicomponent = function(c, on, _strength, _propagate, state)
        pulses[#pulses + 1] = {id = c and c:Id() or "?", on = on and true or false,
                               state = state}
    end
    core.get_ui_root = function()
        return {
            Dimensions = function() return 1920, 1080 end,
            CreateComponent = function() end,
        }
    end
    core.get_screen_resolution = function() return 1920, 1080 end
end

install_ui_stubs()
local UI_FILE = (arg and arg[2])
    or "Modding Files/pack/script/campaign/mod/zzz_derpy_iron_court_ui.lua"
local ui_chunk, ui_err = loadfile(UI_FILE)
assert(ui_chunk, "could not load the panel file: " .. tostring(ui_err))
ui_chunk()
assert(ICUI, "the panel file must define ICUI")
local MAP_FILE = (arg and arg[4])
    or "Modding Files/pack/script/campaign/mod/zzz_derpy_iron_court_ui_map.lua"
local map_chunk, map_err = loadfile(MAP_FILE)
assert(map_chunk, "could not load the Governors map file: " .. tostring(map_err))
map_chunk()
assert(ICUI.gm_sync, "the Governors map file must define ICUI.gm_sync")

local function with_neighbours(has_ex, has_gg)
    EX = has_ex and {BUTTON = "derpy_chd_ex_button", BUTTON_SIZE = 48, BUTTON_GAP = 4} or nil
    GGUI = has_gg and {BTN_SIZE = 44, BTN_GAP = 4} or nil
end

-- The neighbours' slots, computed HERE from their own published formulas rather
-- than from ICUI, so an arithmetic slip in ICUI cannot agree with itself.
local EX_X = BAR_X + BAR_W + 4                 -- off the right end of the strip
local GG_X = EX_X - 44 - 4                     -- one gap left of the Exchange
-- OUR size, not a literal 44. The opener is 55, to match button_toz and
-- button_hellforge; the 44 above is the GUILDS button's size and stays a literal
-- because it is the neighbour's number, not ours. The FORMULA is written out
-- here rather than taken from ICUI, so an arithmetic slip there cannot agree
-- with itself.
local ROW_Y = BAR_Y + math.floor((BAR_H - ICUI.BTN_SIZE) / 2)

-- button_hellforge as CA ships it: 55x55, in the ring at the bottom right. The
-- numbers are its own dimensions attribute out of hud_campaign.twui.xml.
local RING_X, RING_Y, RING_W, RING_H = 1742, 846, 55, 55

check("place_opener actually ends with a button on screen", function()
    -- THE WHOLE CHAIN, retries included. cm:callback is a no-op in this harness,
    -- so every other check stops at btn_anchor and nothing else runs the
    -- create/place/read-back path: a button that logs "placed" and draws nothing
    -- would go unnoticed.
    with_neighbours(true, true)
    ICUI.btn_at = nil
    local opener = nil
    local saved_find, saved_is = find_uicomponent, is_uicomponent
    local saved_root, saved_cb = core.get_ui_root, cm.callback
    local r = {
        Dimensions = function() return 1920, 1080 end,
        Position = function() return 0, 0 end,
        CreateComponent = function(_self, name)
            if name == ICUI.BTN then
                opener = {x = -1, y = -1, shown = false,
                          Position = function(self) return self.x, self.y end,
                          Dimensions = function() return ICUI.BTN_SIZE, ICUI.BTN_SIZE end,
                          MoveTo = function(self, x, y) self.x, self.y = x, y end,
                          SetVisible = function(self, on)
                              IC_NEED_BOOL("SetVisible", on); self.shown = on end,
                          PropagatePriority = function(self, p) self.priority = p end,
                          RegisterTopMost = function(self) self.topmost = true end,
                          SetInteractive = function(_self, on)
                              IC_NEED_BOOL("SetInteractive", on) end}
            end
        end,
    }
    core.get_ui_root = function() return r end
    find_uicomponent = function(_parent, name)
        if name == ICUI.BTN then return opener or false end
        if name == "resources_bar" then return ui_stub.bar end
        return false
    end
    is_uicomponent = function(c) return type(c) == "table" and c.Position ~= nil end
    local fired = 0
    cm.callback = function(_self, fn, _delay)
        fired = fired + 1
        if fired <= ICUI.BTN_TRIES + 2 then fn() end
    end

    logged = {}
    local ok, err = pcall(function() ICUI.place_opener(1) end)

    find_uicomponent, is_uicomponent = saved_find, saved_is
    core.get_ui_root, cm.callback = saved_root, saved_cb
    assert(ok, "place_opener threw: " .. tostring(err))
    assert(opener ~= nil, "no opener component was ever created")
    assert(ICUI.btn_at ~= nil,
        "place_opener gave up without placing the button (" .. fired .. " retries)")
    assert(opener.x == GG_X - ICUI.BTN_SIZE - 4,
        "the button landed at x=" .. opener.x .. ", wanted " .. (GG_X - ICUI.BTN_SIZE - 4))
    assert(opener.y >= 0 and opener.y + ICUI.BTN_SIZE <= 1080,
        "the button is off screen at y=" .. opener.y)
    assert(opener.shown == true, "and it must be explicitly shown")
    -- SHOWN IS NOT DRAWN. The button is a sibling of hud_campaign on the ui root,
    -- so the HUD draws over it and SetVisible(true) buys nothing on its own: a
    -- correct placement in the log and nothing on screen.
    assert(opener.topmost == true,
        "the button was shown but never registered topmost, so the HUD draws over it")
    -- AND IT MUST HAVE SAID SO. `out` is a TABLE with __call, not a function, so a
    -- `type(out) == "function"` guard is never true and every diagnostic line goes
    -- nowhere, including the one naming where this button landed.
    local said = false
    for k = 1, #logged do
        if logged[k]:find("opener placed at", 1, true) then said = true end
    end
    assert(said, "place_opener must LOG where it put the button; " .. #logged
        .. " line(s) reached out()")
    ICUI.btn_at = nil
end)

check("a second run of place_opener is quiet, and re-places the same button",
      function()
    -- WHY THIS MATTERS. Placement re-enters at every FactionTurnStart, which is
    -- the only thing that can recover a campaign whose HUD was not ready inside
    -- the first tick's 12 second window. A re-run that logs every turn buries the
    -- line that names a real move, and one that creates a SECOND component leaves
    -- two buttons on the HUD.
    with_neighbours(true, true)
    ICUI.btn_at = nil
    local created, opener = 0, nil
    local saved_find, saved_is = find_uicomponent, is_uicomponent
    local saved_root, saved_cb = core.get_ui_root, cm.callback
    local r = {
        Dimensions = function() return 1920, 1080 end,
        Position = function() return 0, 0 end,
        CreateComponent = function(_self, name)
            if name ~= ICUI.BTN then return end
            created = created + 1
            opener = {x = -1, y = -1, shown = false,
                      Position = function(self) return self.x, self.y end,
                      Dimensions = function() return ICUI.BTN_SIZE, ICUI.BTN_SIZE end,
                      MoveTo = function(self, x, y) self.x, self.y = x, y end,
                      SetVisible = function(self, on)
                          IC_NEED_BOOL("SetVisible", on); self.shown = on end,
                      RegisterTopMost = function(self) self.topmost = true end,
                      PropagatePriority = function(self, p) self.priority = p end,
                      SetInteractive = function(_self, on)
                          IC_NEED_BOOL("SetInteractive", on) end}
        end,
    }
    core.get_ui_root = function() return r end
    find_uicomponent = function(_parent, name)
        if name == ICUI.BTN then return opener or false end
        if name == "resources_bar" then return ui_stub.bar end
        return false
    end
    is_uicomponent = function(c) return type(c) == "table" and c.Position ~= nil end
    cm.callback = function(_self, fn) fn() end

    logged = {}
    ICUI.place_opener(1)
    local first_lines = #logged
    local first_x, first_y = opener.x, opener.y
    logged = {}
    ICUI.place_opener(1)

    find_uicomponent, is_uicomponent = saved_find, saved_is
    core.get_ui_root, cm.callback = saved_root, saved_cb

    assert(first_lines > 0, "the first placement must log")
    assert(created == 1,
        "a re-run created the button again (" .. created .. " components)")
    assert(opener.x == first_x and opener.y == first_y,
        "a re-run moved the button from " .. first_x .. "," .. first_y
        .. " to " .. opener.x .. "," .. opener.y)
    local noisy = 0
    for k = 1, #logged do
        if logged[k]:find("opener placed at", 1, true) then noisy = noisy + 1 end
    end
    assert(noisy == 0,
        "a re-run that changed nothing still logged " .. noisy .. " placement line(s)")
    ICUI.btn_at = nil
end)

-- THE HUB. With a second Derpy opener installed, one hub button takes this slot
-- and moves this button into a row it shows on hover. Two owners of one MoveTo
-- fight every turn start, so place_opener must still MAKE the button (the hub can
-- only manage what exists) and must not move or show it.
check("place_opener defers to the hub when managed, and places itself when not", function()
    with_neighbours(true, true)
    ICUI.btn_at = nil
    local opener, moves, shown = nil, 0, nil
    local saved_find, saved_is = find_uicomponent, is_uicomponent
    local saved_root, saved_cb, saved_hub = core.get_ui_root, cm.callback, DERPY_HUB
    local r = {
        Dimensions = function() return 1920, 1080 end,
        Position = function() return 0, 0 end,
        CreateComponent = function(_self, name)
            if name ~= ICUI.BTN then return end
            opener = {x = -1, y = -1,
                      Position = function(self) return self.x, self.y end,
                      Dimensions = function() return ICUI.BTN_SIZE, ICUI.BTN_SIZE end,
                      MoveTo = function(self, x, y) self.x, self.y = x, y; moves = moves + 1 end,
                      SetVisible = function(_self, on)
                          IC_NEED_BOOL("SetVisible", on); shown = on end,
                      RegisterTopMost = function() end,
                      PropagatePriority = function() end,
                      SetInteractive = function() end}
        end,
    }
    core.get_ui_root = function() return r end
    find_uicomponent = function(_parent, name)
        if name == ICUI.BTN then return opener or false end
        if name == "resources_bar" then return ui_stub.bar end
        return false
    end
    is_uicomponent = function(c) return type(c) == "table" and c.Position ~= nil end
    cm.callback = function() end

    -- AND STILL WRITES THE TOOLTIP, WHICH IS WHAT GATES THE PULSE. A managed button
    -- that skips update_opener_tip keeps the static twui tooltip and never pulses, so
    -- the hub (which reads ICUI.pulsing) never pulses either, for the whole first
    -- turn of a load. The quiet turn-start call must still not, as unmanaged: no
    -- loc read from a turn handler.
    local saved_tip, tips = ICUI.update_opener_tip, 0
    ICUI.update_opener_tip = function() tips = tips + 1 return true end
    DERPY_HUB = {version = 1, manages = function(key) return key == "ic" end}
    local ok, err = pcall(ICUI.place_opener, 1)
    local managed_moves, managed_shown, managed_tips = moves, shown, tips
    pcall(ICUI.place_opener, 1, true)
    local quiet_tips = tips - managed_tips
    ICUI.update_opener_tip = saved_tip
    DERPY_HUB = {version = 1, manages = function() return false end}
    ICUI.btn_at = nil
    pcall(ICUI.place_opener, 1)

    DERPY_HUB = saved_hub
    find_uicomponent, is_uicomponent = saved_find, saved_is
    core.get_ui_root, cm.callback = saved_root, saved_cb
    ICUI.btn_at = nil
    assert(ok, "place_opener threw: " .. tostring(err))
    assert(opener ~= nil, "managed, the button must still be created for the hub to find")
    assert(managed_moves == 0, "managed, place_opener still moved the button")
    assert(managed_shown == nil, "managed, place_opener still set its visibility")
    assert(moves == 1 and shown == true, "unmanaged, it must place and show itself as before")
    assert(managed_tips == 1, "managed, place_opener never wrote the tooltip, so the court "
           .. "button keeps the static one and the hub never pulses")
    assert(quiet_tips == 0, "managed, the quiet turn-start call wrote the tooltip from a "
           .. "turn handler")
end)

check("the court registers with the hub and reports its own grey and pulse", function()
    local mine
    for _, e in ipairs(DERPY_HUB_QUEUE or {}) do
        if e.key == "ic" then mine = e end
    end
    assert(mine, "no DERPY_HUB_QUEUE entry with key ic")
    assert(mine.button == ICUI.BTN and mine.order == 1, "wrong button or order")
    assert(mine.label() == "The Iron Court", "label was " .. tostring(mine.label()))
    local saved_find = find_uicomponent
    local stub = setmetatable({Id = function() return ICUI.BTN end,
                               Position = function() return 0, 0 end},
                              {__index = function() return function() end end})
    find_uicomponent = function(_p, name)
        if name == ICUI.BTN then return stub end
        return false
    end
    ICUI.gate_opener(false, false)
    local grey_live, grey_wants = mine.live(), mine.wants()
    -- gate_opener(waiting, live): live with nothing waiting, then live and waiting,
    -- which is the court's own pulse.
    ICUI.gate_opener(false, true)
    local idle_live, idle_wants = mine.live(), mine.wants()
    ICUI.gate_opener(true, true)
    local wait_wants = mine.wants()
    ICUI.gate_opener(false, true)
    find_uicomponent = saved_find
    assert(grey_live == false and grey_wants == false, "greyed: live/wants must be false/false")
    assert(idle_live == true and idle_wants == false, "live and idle: true/false")
    assert(wait_wants == true, "a pulsing button must report that it wants attention")
end)

check("no turn handler writes the court button's tooltip", function()
    -- The tooltip names parties, offices and bands through the loc, and a loc
    -- lookup inside a turn handler takes the Exchange down at turn 1 of a fresh
    -- campaign, pcall or not. ic_opener_place must not write it whenever the
    -- button moves (exactly the campaign whose first tick failed to place it), and
    -- ic_turn_end must not write it through close().
    with_neighbours(true, true)
    ICUI.btn_at = nil
    local opener, panel_up = nil, true
    local saved_find, saved_is = find_uicomponent, is_uicomponent
    local saved_root, saved_cb = core.get_ui_root, cm.callback
    local saved_tip, saved_humans = ICUI.update_opener_tip, cm.get_human_factions
    local r = {
        Dimensions = function() return 1920, 1080 end,
        Position = function() return 0, 0 end,
        CreateComponent = function(_self, name)
            if name ~= ICUI.BTN then return end
            opener = {x = -1, y = -1,
                      Position = function(self) return self.x, self.y end,
                      Dimensions = function() return ICUI.BTN_SIZE, ICUI.BTN_SIZE end,
                      MoveTo = function(self, x, y) self.x, self.y = x, y end,
                      SetVisible = function(_self, on) IC_NEED_BOOL("SetVisible", on) end,
                      RegisterTopMost = function() end,
                      PropagatePriority = function() end,
                      SetInteractive = function(_self, on)
                          IC_NEED_BOOL("SetInteractive", on) end}
        end,
    }
    local panel = {Position = function() return 0, 0 end,
                   DestroyChildren = function() end,
                   Destroy = function() panel_up = false end}
    core.get_ui_root = function() return r end
    find_uicomponent = function(_parent, name)
        if name == ICUI.BTN then return opener or false end
        if name == ICUI.PANEL then return panel_up and panel or false end
        if name == "resources_bar" then return ui_stub.bar end
        return false
    end
    is_uicomponent = function(c) return type(c) == "table" and c.Position ~= nil end
    cm.callback = function() end
    cm.get_human_factions = function() return {F} end
    local tips = 0
    ICUI.update_opener_tip = function() tips = tips + 1 end
    local ok, err = pcall(function()
        core.listeners["ic_opener_place"]({})
        assert(opener and ICUI.btn_at, "the button was not placed, so this proves nothing")
        local fac = {is_null_interface = function() return false end,
                     name = function() return F end}
        core.listeners["ic_turn_end"]({faction = function() return fac end})
        assert(not panel_up, "the court stayed open, so this proves nothing")
    end)
    find_uicomponent, is_uicomponent = saved_find, saved_is
    core.get_ui_root, cm.callback = saved_root, saved_cb
    ICUI.update_opener_tip, cm.get_human_factions = saved_tip, saved_humans
    ICUI.btn_at = nil
    assert(ok, err)
    assert(tips == 0, "a turn handler wrote the tooltip " .. tips .. " time(s)")
end)

check("the opener sits immediately left of the guilds button", function()
    with_neighbours(true, true)
    local x, y = ICUI.btn_anchor()
    assert(x == GG_X - ICUI.BTN_SIZE - 4,
        "expected " .. (GG_X - ICUI.BTN_SIZE - 4) .. " got " .. tostring(x))
    assert(y == ROW_Y, "centred on the strip, got " .. tostring(y))
    assert(x + ICUI.BTN_SIZE <= GG_X, "overlaps the guilds button")
    assert(x + ICUI.BTN_SIZE <= EX_X, "overlaps the exchange button")
end)

check("the gap is OUR width, not the neighbour's", function()
    -- Ours is 55 and the Guilds button 44, so "offset by their width" and "offset
    -- by ours" already differ by 11px. The widened neighbour below is kept anyway:
    -- if the sizes ever agree again this check would silently go vacuous, and
    -- taking the neighbour's width is the easy way to overlap them the day CA or
    -- that mod changes a size.
    EX = {BUTTON = "derpy_chd_ex_button", BUTTON_SIZE = 48, BUTTON_GAP = 4}
    GGUI = {BTN_SIZE = 60, BTN_GAP = 4}
    local gg_x = EX_X - 60 - 4               -- where a 60px guilds button starts
    local x = ICUI.btn_anchor()
    assert(x == gg_x - ICUI.BTN_SIZE - 4,
        "must offset by our own 44, not the neighbour's 60: expected "
        .. (gg_x - ICUI.BTN_SIZE - 4) .. " got " .. tostring(x))
    assert(x + ICUI.BTN_SIZE <= gg_x, "and it must not overlap them")
end)

