check("an office card shows its holder's face, a vacant one a silhouette", function()
    IC.state = {}
    local ghorth = make_character(21, ANY_SEAT, "legion", "prov_a")
    make_faction(F, IC.CHD_SUBCULTURE, {ghorth}, {"prov_a"})
