        IC.mp_send("no_such_faction_key", "dismiss", "warden")
        assert(#sent == 0, "a trigger went out with no cqi to carry")
    end)
    IC.dismiss = was
    if not ok then error(err, 0) end
    assert(called == 0, "the unsendable action ran on this machine")
end)

