check("the fill button shows its plan on the offices tab and answers every click", function()
    fill_fixture()
    local function draw(view)
        local fill
        ICUI.view = view
        with_fake_panel(function(panel)
            ICUI.refresh()
            fill = panel.children.ic_fill
            fill = {visible = fill.visible, text = plain(fill.text or ""),
                    red = is_red(fill), tip = fill.tooltip or ""}
        end)
        return fill
    end
    local b = draw("offices")
    assert(b.visible == true, "the button is not on the offices tab")
    assert(b.text == "Fill Empty Seats" and not b.red, "the button reads " .. b.text)
    assert(b.tip:find(ICUI.office_name("forge") .. ": ", 1, true)
           and b.tip:find(ICUI.character_name(IC.character_by_cqi(F, 701)), 1, true),
           "the tooltip does not show the plan: " .. b.tip)
    for _, view in ipairs({"court", "govs", "intrigue", "log", "petitions"}) do
        assert(draw(view).visible == false, "the button shows on the " .. view .. " tab")
    end
    -- THE CLICK, in single player: straight through, and the notice says so.
    ICUI.view = "offices"
    with_fake_panel(function()
        ICUI.on_fill_click()
    end)
    assert(IC.court(F).offices["forge"] == 701, "the click seated nobody")
    assert(ICUI.notice and ICUI.notice:find("3 seats filled", 1, true),
           "the answer reads " .. tostring(ICUI.notice))
    -- NOTHING LEFT TO FILL: red, and a click says why rather than nothing.
    b = draw("offices")
    assert(b.red, "a button with nothing to do is not red")
    ICUI.notice = nil
    local sent = 0
    local was = IC.mp_send
    IC.mp_send = function(...) sent = sent + 1 return was(...) end
    with_fake_panel(function() ICUI.on_fill_click() end)
    IC.mp_send = was
    assert(sent == 0, "a click with nothing to fill was sent")
    assert(ICUI.notice and ICUI.notice ~= "", "a click with nothing to fill said nothing")
    ICUI.notice, ICUI.view = nil, "court"
    cm.get_human_factions = function() return {} end
end)

check("a seat is held for ten turns on every difficulty", function()
    -- THE TERM LENGTH IS NOT A DIFFICULTY KNOB: a term of five makes the court
    -- easier, not harder, since every end is a free chance to re-seat and a full
    -- court has three seats to refill every turn.
    for _, name in ipairs({"gentle", "default", "harsh", "ruthless"}) do
        with_mct(stub_mct({preset = name}), function()
            IC.state = {}
            saved["derpy_ic_tuned"] = nil
            saved["derpy_ic_" .. F] = nil
            rng(nil)
            make_faction(F, IC.CHD_SUBCULTURE, {}, {})
            cm.get_human_factions = function() return {F} end
            local ok, err = pcall(IC.first_tick)
            cm.get_human_factions = function() return {} end
            assert(ok, "the first tick raised: " .. tostring(err))
            assert(IC.TUNE.term_turns == 10,
                   name .. " holds a seat for " .. IC.TUNE.term_turns .. " turns")
        end)
    end
end)

check("a stalled office pays nothing until its turn, and ends with its man", function()
    -- A STALLED OFFICE: its faction-wide bonus off until a turn, and never longer
    -- than the man it was aimed at holds it.
    IC.state = {}
    turn = 5
    local man = make_character(601, ANY_SEAT, "forge")
    local other = make_character(602, ANY_SEAT, "chain")
    make_faction(F, IC.CHD_SUBCULTURE, {man, other}, {})
    IC.add_house(F, IC.CROWN)
    IC.add_house(F, "forge")
    IC.add_house(F, "chain")
    local office = IC.OFFICES[1].slug
    local bundle = IC.office_bundle(office)
    IC.court(F).offices[office] = 601
    applied = {}
    IC.apply_office_bundles(F)
    assert(applied[bundle], "a held office pays nothing before any stall")
    assert(IC.stall_office(F, office, 3, "chain", "sabotage"), "the stall was refused")
    assert(not applied[bundle], "a stalled office still pays")
    assert(IC.stalled_for(F, office) == 3, "stalled for " .. IC.stalled_for(F, office))
    -- A RELOAD KEEPS IT.
    IC.save(F)
    IC.state = {}
    IC.load(F)
    assert(IC.stalled_for(F, office) == 3, "the save forgot the stall")
    -- ITS TURN COMES.
    turn = 8
    IC.apply_office_bundles(F)
    assert(applied[bundle], "the stall outlived its turns")
    assert(IC.court(F).stalled[office] == nil, "an ended stall stayed in the save")
    -- A MAN OF ANOTHER PARTY IN THE SEAT ENDS IT.
    turn = 9
    IC.stall_office(F, office, 3, "chain", "sabotage")
    IC.court(F).offices[office] = 602
    IC.apply_office_bundles(F)
    assert(IC.court(F).stalled[office] == nil,
        "the stall outlived the man it was aimed at")
    -- AND AN EMPTY SEAT CANNOT BE STALLED.
    IC.court(F).offices[office] = nil
    assert(not IC.stall_office(F, office, 3, "chain", "sabotage"),
        "an empty seat was stalled")
end)

check("a court saved before stalls and news loads with neither", function()
    -- Fields 11 and 12 came later; a save without them must not shift anything
    -- or invent a stall.
    IC.state = {}
    turn = 5
    make_faction(F, IC.CHD_SUBCULTURE, {make_character(611, ANY_SEAT, "forge")}, {})
    IC.add_house(F, IC.CROWN)
    IC.add_house(F, "forge")
    IC.court(F).offices[IC.OFFICES[1].slug] = 611
    local packed = IC.pack(F)
    local old = string.match(packed, "^(.*)|[^|]*|[^|]*$")
    assert(old, "the packed court has fewer than twelve fields: " .. packed)
    IC.state = {}
    IC.unpack(F, old)
    local court = IC.court(F)
    assert(court.offices[IC.OFFICES[1].slug] == 611, "an old save lost its office")
    assert(next(court.stalled) == nil, "an old save loaded with a stall")
    assert(#(court.news or {}) == 0, "an old save loaded with news")
end)

