-- THE ROLE A KEY WAS DRAWN FOR, read back off IC.REBEL_POOLS.
local function rebel_role_of(key)
    for role, pool in pairs(IC.REBEL_POOLS) do
        for _, u in ipairs(pool) do
            if u[1] == key then return role end
        end
    end
    return nil
end

check("a rising with nobody leaving is a Hashut army, not a copy of yours", function()
    -- A REBEL PARTY DOES NOT COPY THE LEADER'S UNITS. With no lord left, a kit
    -- that walks the faction's own armies finds the leader's first; the army is
    -- built from a proper composition, based on Hashut's crisis events.
    party_of(1, 0)
    local lord = IC.character_by_cqi(F, 121)
    lord._force = true
    lord._units = {"derpy_leaders_own_a", "derpy_leaders_own_b"}
    rng(nil)
    local kit = IC.rebel_kit(F, nil)
    assert(#kit == IC.TUNE.rebel_units, "the army holds " .. #kit .. " units")
    local roles = {}
    for i = 1, #kit do
        assert(kit[i] ~= "derpy_leaders_own_a" and kit[i] ~= "derpy_leaders_own_b",
            "slot " .. i .. " was copied off the player's army")
        local role = rebel_role_of(kit[i])
        assert(role, "slot " .. i .. " is " .. tostring(kit[i])
            .. ", which no role of the Hashut army lists")
        roles[role] = (roles[role] or 0) + 1
    end
    -- THE SHAPE IS THE DRAFT'S: a line, missiles, a screen, horse, beasts, guns.
    local want = {}
    for i = 1, IC.TUNE.rebel_units do
        local role = IC.REBEL_DRAFT[(i - 1) % #IC.REBEL_DRAFT + 1]
        want[role] = (want[role] or 0) + 1
    end
    for role, n in pairs(want) do
        assert((roles[role] or 0) == n, role .. ": " .. tostring(roles[role])
            .. " unit(s), the draft asks " .. n)
    end
end)

check("a rebel army is rolled, and never fields more than two of one unit", function()
    -- THE LOWEST ROLL EVERY TIME is the harness's default; the highest is the
    -- other end. Two different armies out of two different dice is what "rolled"
    -- means, and the cap is what keeps either from being six of one thing.
    party_of(1, 0)
    rng(nil)
    local low = IC.rebel_kit(F, nil)
    local high_rolls = {}
    for i = 1, 200 do high_rolls[i] = 1000 end
    rng(high_rolls)
    local high = IC.rebel_kit(F, nil)
    rng(nil)
    assert(table.concat(low, ",") ~= table.concat(high, ","),
        "the lowest and the highest dice made the same army")
    for _, kit in ipairs({low, high}) do
        local seen = {}
        for i = 1, #kit do
            seen[kit[i]] = (seen[kit[i]] or 0) + 1
            assert(seen[kit[i]] <= IC.REBEL_UNIT_CAP,
                kit[i] .. " is in one rebel army " .. seen[kit[i]] .. " times")
        end
    end
end)

check("a lord who leaves brings his army, filled out into a proper one", function()
    -- HIS OWN UNITS FIRST, modded or not - that is how a unit mod reaches the
    -- rebels. The rest is the Hashut draft, not his stack again in order.
    party_of(1, 0)
    local lord = IC.character_by_cqi(F, 121)
    lord._force = true
    lord._units = {"derpy_modded_thing_a", "derpy_modded_thing_b"}
    rng(nil)
    local kit = IC.rebel_kit(F, 121)
    assert(kit[1] == "derpy_modded_thing_a" and kit[2] == "derpy_modded_thing_b",
        "the kit opened with " .. tostring(kit[1]) .. ", " .. tostring(kit[2]))
    assert(#kit == IC.TUNE.rebel_units, "the army holds " .. #kit .. " units")
    for i = 3, #kit do
        assert(rebel_role_of(kit[i]), "slot " .. i .. " is " .. tostring(kit[i])
            .. " - padded with his own stack again, or with nothing")
    end
end)

check("an AI court touched before its own turn after a load keeps its parties", function()
    -- After a load, AI courts are read on their own FactionTurnStart. A lord of
    -- theirs ranking up earlier in the round reaches IC.court, which must not
    -- build an EMPTY court that add_standing then saves over the real one, or
    -- the next turn rolls a whole new court.
    IC.state = {}
    factions = {}
    local man = make_character(4401, ANY_SEAT, "forge")
    make_faction(F, IC.CHD_SUBCULTURE, {man}, {})
    IC.add_house(F, IC.CROWN)
    IC.add_house(F, "forge")
    IC.save(F)
    IC.state = {}                      -- the load: nothing in memory yet
    IC.register()
    core.listeners["ic_rank"]({character = function() return man end,
                               ranks_gained = function() return 1 end})
    assert(IC.court(F).houses.forge, "the court in memory lost its parties")
    IC.state = {}
    IC.load(F)
    assert(IC.court(F).houses.forge, "an empty court was saved over the real one")
end)

check("on Ruthless the last warning still comes before a secession", function()
as_player(function()
    -- RUTHLESS COUNTS DOWN FROM 3, and a last warning waiting for the clock to
    -- READ warn_turns (3) after a tick never comes once a three-turn clock has
    -- started. It lands one turn after the start card.
    local was = IC.TUNE.secede_turns
    IC.TUNE.secede_turns = 3
    local ok, err = pcall(function()
        local court = angry_court()
        local soon = IC.EVENTS.secede_soon[1]
        shown = {}
        local warned_on, gone_on
        for n = 1, IC.TUNE.secede_turns + 4 do
            IC.tick_secession(F)
            if not warned_on and cards_at(soon) > 0 then warned_on = n end
            if not court.houses.legion then gone_on = n break end
        end
        assert(gone_on, "the party never left")
        assert(warned_on, "a three-turn count ran out with no last warning")
        assert(gone_on - warned_on == 2, "the last warning landed "
            .. (gone_on - warned_on) .. " turns before the secession, not 2")
        assert(cards_at(soon) == 1, cards_at(soon) .. " last warnings, not one")
    end)
    IC.TUNE.secede_turns = was
    assert(ok, err)
end)
end)

check("a dead court takes no place in the AI rotation", function()
    -- The rotation's period counts living Chaos Dwarf factions only: counting
    -- every one ever leaves three living AI courts late in a campaign waiting a
    -- whole period of dead ones between turns.
    local keep = cm.get_human_factions
    cm.get_human_factions = function() return {"wh3_dlc23_chd_conclave"} end
    factions = {}
    local living = {}
    for i = 1, #IC.ORIGINS do
        local key = IC.ORIGINS[i].faction
        if key and key ~= "wh3_dlc23_chd_conclave" then
            local f = make_faction(key, IC.CHD_SUBCULTURE, {}, {})
            if #living < IC.TUNE.ai_party_courts then
                living[#living + 1] = key
            else
                f._dead = true
            end
        end
    end
    local ok, err = pcall(function()
        for t = 1, 4 do
            turn = t
            for _, key in ipairs(living) do
                assert(IC.party_turn_due(key), key .. " waited on turn " .. t
                    .. " though only " .. #living .. " AI courts are left")
            end
        end
    end)
    cm.get_human_factions = keep
    assert(ok, err)
end)

