            assert(panel.interactive == true, tab .. " left the panel letting clicks through")
            assert(pin.destroyed and gm_pin(holder, 1) == nil, tab .. " left the pins up")
            if tab == "ic_help" then map_click("ic_help") end
        end
    end)
end)

