        -- AND THE THIRD CLICK IS MAP ORDER AGAIN.
        ICUI.pick = nil
        map_click("ic_gm_sort_1")
        assert(ICUI.sort.govs == 1, "the third click did not hand back map order")
    end)
    IC_TEST_LOC = nil
    ICUI.sort.govs, ICUI.sort_desc.govs = 1, false
end)

